import * as React from "react"
import Layout from "../components/layout"
import { graphql } from "gatsby"
import Seo from "../components/seo"
import Services from "../components/Services"
import ContentBlockPat from "../components/construct/ContentBlockPat"

export const Head = ({ data }) => <Seo title="Algunos de nuestros servicios" description={data.allPagesJson.nodes[0].content.description} />

const ServicesPage = ({ data }) => (
  <Layout>
    <section className="construct-contact-page-area section_50">
      <div className="container">
        <div className="row">
          <div className="col-md-10">
            <div className="construct-contact-desc">
              <h1>{data.allPagesJson.nodes[0].content.title}</h1>
              <p>{data.allPagesJson.nodes[0].content.description}</p>
            </div>
          </div>
        </div>

        <ContentBlockPat />
        <Services data={data}></Services>
      </div>
    </section>
  </Layout>
)

export const query = graphql`
  query {
     allPagesJson(filter: { idPage: { eq: "servicios" } }) {
      nodes {
        idPage
        content {
          description
          title
        }
      }
    }

    servicios: allServiciosJson(
      filter: { href: { nin: "/servicios/medicion-pat/" } }
    ) {
      nodes {
        title
        description
        href
        data
        {
          title
          description
        }
        image {
          childImageSharp {
            gatsbyImageData(
              placeholder: BLURRED
              formats: [AUTO, WEBP, AVIF]
              width: 370
              height: 188
            )
          }
        }
      }
    }
  }
`

export default ServicesPage
